//! View-authoring backend: MCP-tool-facing services for agent-driven
//! `.sui` editing.
//!
//! Surfaces:
//! - [`types`] — request/response shapes shared with the chrome edit-mode UI.
//!   The frontend imports the TS bindings generated by `cargo xtask gen-types`.
//! - [`snapshot`] — persists prior view sources as artifacts so writes are
//!   reversible. Backed by the `view_snapshots` built-in collection.
//! - [`capability`] — per-session, in-memory grants for the `view.*` MCP
//!   tools. Cleared on daemon restart / explicit exit.

pub mod capability;
pub mod snapshot;
pub mod types;

#[cfg(test)]
mod tests;

pub use capability::{
    ViewEditCapability, grant, grants_snapshot, has_grant, revoke, revoke_session,
};
pub use snapshot::{
    VIEW_SNAPSHOTS_COLLECTION_ID, delete_snapshot, ensure_view_snapshots_collection,
    list_snapshots, read_snapshot, snapshot_view, space_context_for, view_snapshots_schema,
};
pub use types::*;
